int kvm_create_device(struct kvm *kvm, struct kvm_create_device *cd)
{
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	int r;

	if (cd->type >= KVM_DEV_TYPE_MAX)
		return -EINVAL;

	ops = kvm_dev_ops[cd->type];
	if (!ops)
		return -ENODEV;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	dev->ops = ops;
	dev->kvm = kvm;
	mutex_lock(&kvm->lock);
	r = ops->create(dev, cd->fd);
	if (r) {
		mutex_unlock(&kvm->lock);
		goto out_free;
	}

	list_add(&dev->list, &kvm->devices);
	mutex_unlock(&kvm->lock);

	if (ops->init) {
		r = ops->init(dev);
		if (r)
			goto out_remove;
	}

	cd->fd = kvm_dev_ioctl_create_fd(dev);
	return 0;

out_remove:
	mutex_lock(&kvm->lock);
	list_del(&dev->list);
	mutex_unlock(&kvm->lock);
out_free:
	kfree(dev);
	return r;
}

int kvm_create_device(struct kvm *kvm, struct kvm_create_device *cd)
{
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	int r, fd;

	if (cd->type >= KVM_DEV_TYPE_MAX)
		return -EINVAL;

	ops = kvm_dev_ioctl_ops[cd->type];
	if (!ops)
		return -EINVAL;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	kvm_get_kvm(kvm);
	dev->kvm = kvm;
	dev->ops = ops;

	r = ops->create(dev, cd->fd);
	if (r) {
		kvm_put_kvm(dev->kvm);
		kfree(dev);
		return r;
	}

	spin_lock(&kvm->devices_lock);
	list_add(&dev->list, &kvm->devices);
	spin_unlock(&kvm->devices_lock);

	if (ops->init) {
		r = ops->init(dev);
		if (r) {
			kvm_remove_device(dev);
			kfree(dev);
			return r;
		}
	}

	fd = kvm_dev_ioctl_create_device(dev);
	if (fd < 0) {
		kvm_remove_device(dev);
		kfree(dev);
		return fd;
	}

	cd->fd = fd;
	return 0;
}

int kvm_device_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	int ret = 0;

	if (cd->type >= KVM_DEV_TYPE_MAX || !kvm_device_ops[cd->type])
		return -EINVAL;

	ops = kvm_device_ops[cd->type];
	if (!ops->create)
		return -EINVAL;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	kvm_get_kvm(kvm);
	mutex_lock(&kvm->lock);
	dev->kvm = kvm;
	dev->ops = ops;
	dev->id = cd->id;

	if (cd->flags & KVM_CREATE_DEVICE_TEST) {
		ret = 0;
		goto out_unlock;
	}

	ret = ops->create(dev, cd->flags);
	if (ret)
		goto out_unlock;

	list_add(&dev->list, &kvm->devices);
	if (ops->init)
		ops->init(dev);

	mutex_unlock(&kvm->lock);
	kvm_get_dev_fd(dev);
	return 0;

out_unlock:
	mutex_unlock(&kvm->lock);
	kvm_put_kvm(kvm);
	kfree(dev);
	return ret;
}

int kvm_device_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	int ret = -EINVAL;
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	struct kvm_device *tmp;
	struct kvm_device *new_dev = NULL;
	int i;

	if (cd->type >= KVM_DEV_TYPE_MAX)
		goto out;

	ops = kvm_device_ops[cd->type];
	if (!ops)
		goto out;

	if (cd->flags & KVM_CREATE_DEVICE_TEST) {
		ret = 0;
		goto out;
	}

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		goto out;

	new_dev = dev;
	dev->ops = ops;
	dev->kvm = kvm;

	mutex_lock(&kvm->lock);
	list_for_each_entry(tmp, &kvm->devices, list) {
		if (tmp->id == cd->type) {
			ret = -EEXIST;
			goto unlock;
		}
	}

	dev->id = cd->type;
	list_add(&dev->list, &kvm->devices);
	mutex_unlock(&kvm->lock);

	if (ops->init && ops->init(dev) < 0)
		goto failed;

	ret = kvm_dev_ioctl_create_device(kvm, dev, &cd->fd);
	if (ret < 0)
		goto failed;

	return 0;

failed:
	mutex_lock(&kvm->lock);
	list_del(&dev->list);
	mutex_unlock(&kvm->lock);
	kvm_device_free(dev);
out:
	return ret;
}

#include <linux/kvm.h>
#include <linux/slab.h>
#include <linux/file.h>

int kvm_device_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	int ret = 0;

	if (!kvm)
		return -EINVAL;

	ops = kvm_find_device_ops(cd->type);
	if (!ops)
		return -ENODEV;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	mutex_lock(&kvm->lock);
	dev->kvm = kvm;
	dev->ops = ops;

	ret = ops->create(dev, cd->flags);
	if (ret < 0)
		goto unlock;

	list_add(&dev->list, &kvm->devices);

	mutex_unlock(&kvm->lock);

	if (ops->init) {
		ret = ops->init(dev);
		if (ret < 0)
			goto fail;
	}

	cd->fd = get_unused_fd_flags(0);
	if (cd->fd < 0) {
		ret = cd->fd;
		goto fail;
	}

	fd_install(cd->fd, &dev->file);

	return 0;

fail:
	mutex_lock(&kvm->lock);
	list_del(&dev->list);
	mutex_unlock(&kvm->lock);

	kfree(dev);
	return ret;
unlock:
	mutex_unlock(&kvm->lock);
	return ret;
}
